#!/usr/bin/env node
// Pri Learning · Prithagoras question coverage (all years and courses)
//
// One row per Prithagoras skill: distinct instances and forms (from the committed
// docs/content/question-capacity.md, itself generated by tools/question-capacity.mjs),
// and diagram coverage (the share of issued questions that carry a generated figure,
// sampled over the issued cells). Lists exactly what is below target.
//   node tools/question-coverage.mjs [YYYY-MM-DD]   # writes docs/content/questions-coverage-nsw-<date>.md
// SYNTHETIC: in-process generation; no student or examiner evidence.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../', import.meta.url));
const date = process.argv[2] || new Date().toISOString().slice(0, 10);
const OUT = `${ROOT}docs/content/questions-coverage-nsw-${date}.md`;
const SEEDS = 200;

const { generateQuestion, loadAllBanks } = await import('../client/src/engine/generators/index.js');
const { NSW_ISSUED_CELLS } = await import('../client/src/engine/nswIssuedCells.js');
await loadAllBanks();

const report = readFileSync(`${ROOT}docs/content/question-capacity.md`, 'utf8');
const block = report.slice(report.indexOf('## Prithagoras'), report.indexOf('## Priyabhata'));
const cap = new Map();
for (const line of block.split('\n')) {
  const m = /^\| `([^`]+)` \| (\d+) \| (≥ )?([\d.]+[kM]?) \| (\d+) \| ([^|]*)\| ([^|]*)\|/.exec(line) || /^\| `([^`]+)` \| (\d+) \| (≥ )?([\d.]+[kM]?) \| (\d+) \| ()([^|]*)\|/.exec(line);
  if (m) cap.set(m[1], { cells: Number(m[2]), instances: m[4], forms: Number(m[5]) });
}
const num = s => (s.endsWith('M') ? parseFloat(s) * 1e6 : s.endsWith('k') ? parseFloat(s) * 1e3 : parseFloat(s));
const course = id => (/^y(7|8|9|10)-/.test(id) ? 'Years 7–10' : /^ms/.test(id) ? 'Standard' : /^y(11|12)-/.test(id) ? 'Advanced' : /^mex-/.test(id) ? 'Extension 2' : /^me/.test(id) ? 'Extension 1' : 'Other');

const rows = [];
for (const id of Object.keys(NSW_ISSUED_CELLS).sort()) {
  let drawn = 0, figs = 0, errors = 0;
  for (const d of NSW_ISSUED_CELLS[id]) for (let s = 1; s <= SEEDS; s++) {
    try { const q = generateQuestion(id, d, s * 7919 + d * 31); drawn++; if (q.figure) figs++; } catch { errors++; }
  }
  const c = cap.get(id) || { cells: NSW_ISSUED_CELLS[id].length, instances: '?', forms: 0 };
  rows.push({ id, course: course(id), ...c, inst: num(String(c.instances)), diagramPct: drawn ? Math.round(100 * figs / drawn) : 0, errors });
}
const below = r => !(r.inst >= 10000 && r.forms >= 5);
const order = ['Years 7–10', 'Standard', 'Advanced', 'Extension 1', 'Extension 2', 'Other'];
let md = `# Prithagoras question coverage — ${date}

<!-- Generated by tools/question-coverage.mjs from docs/content/question-capacity.md and a sample of issued questions. Do not edit by hand. -->

Every Prithagoras skill (one generator; its issued difficulty cells): **distinct instances** and **structural forms** from the capacity report (Chao1 collision estimate; forms = largest number of number-masked prompt shapes in one cell), and **diagram coverage** = the percentage of ${SEEDS} sampled questions per issued cell that carry a generated figure. Targets: ≥ 10,000 instances and ≥ 5 forms per skill. SYNTHETIC: in-process generation; no student or examiner evidence.

**${rows.length} skills; ${rows.filter(r => !below(r)).length} meet both targets; ${rows.filter(below).length} below.**

## Below target

${rows.filter(below).length ? rows.filter(below).map(r => `- \`${r.id}\` (${r.course}): ${r.instances} instances, ${r.forms} forms`).join('\n') : 'None.'}

## Diagram coverage

${rows.filter(r => r.diagramPct > 0).length} of ${rows.length} skills generate at least one figure. Skills with no generated diagram at all are listed per course below; whether a given skill benefits from one is a content decision, and adding a figure needs a builder in \`client/src/engine/figures.js\` plus an accuracy test that the drawn numbers equal the prompt's.

`;
for (const c of order) {
  const list = rows.filter(r => r.course === c);
  if (!list.length) continue;
  md += `## ${c}\n\n| Skill | Cells | Distinct instances | Forms | Diagram coverage | Meets targets |\n| --- | --- | --- | --- | --- | --- |\n`;
  for (const r of list) md += `| \`${r.id}\` | ${r.cells} | ${r.instances} | ${r.forms} | ${r.diagramPct}% | ${below(r) ? 'no' : 'yes'} |\n`;
  md += `\nNo generated diagram: ${list.filter(r => r.diagramPct === 0).map(r => `\`${r.id}\``).join(', ') || 'none'}\n\n`;
}
writeFileSync(OUT, md);
console.log(`wrote ${OUT.replace(ROOT, '')} — ${rows.length} skills, ${rows.filter(below).length} below target`);
